#include "stdlib/lapack/base/dlasyf.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define ITERATIONS 200
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Resets and factors a bounded panel, then validates its outputs.
*
* @param N        matrix order
* @param NB       panel width
* @param uplo     stored triangle
* @param ndarray  whether to use explicit indexing
* @return         elapsed seconds or -1 on failure
*/
static double benchmark( const LAPACK_INT N, const LAPACK_INT NB, const LAPACK_UPLO uplo, const int ndarray ) {
	double *original;
	double *A;
	double *W;
	LAPACK_INT *IPIV;
	LAPACK_INT KB;
	LAPACK_INT expected;
	LAPACK_INT start;
	LAPACK_INT stop;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	double elapsed;
	double t;
	int k;

	original = (double *)malloc( (size_t)(N*N) * sizeof( double ) );
	A = (double *)malloc( (size_t)(N*N) * sizeof( double ) );
	W = (double *)malloc( (size_t)(N*NB) * sizeof( double ) );
	IPIV = (LAPACK_INT *)malloc( (size_t)N * sizeof( LAPACK_INT ) );
	if ( original == NULL || A == NULL || W == NULL || IPIV == NULL ) {
		fprintf( stderr, "Error allocating benchmark buffers.\n" );
		free( original );
		free( A );
		free( W );
		free( IPIV );
		return -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		IPIV[ i ] = -99;
		for ( j = 0; j < N; j++ ) {
			if ( i == j ) {
				original[ (i*N)+j ] = (double)N + 2.0;
			} else if ( ( uplo == LAPACK_UPPER_TRIANGLE && i < j ) || ( uplo == LAPACK_LOWER_TRIANGLE && i > j ) ) {
				original[ (i*N)+j ] = 0.25;
			} else {
				original[ (i*N)+j ] = 999.0;
			}
		}
	}
	for ( i = 0; i < N*NB; i++ ) {
		W[ i ] = -9.0;
	}
	expected = ( N <= NB ) ? N : NB-1;
	KB = 0;
	info = 0;
	t = tic();
	for ( k = 0; k < ITERATIONS; k++ ) {
		// Include input reset: factoring the previous factors would be a different workload.
		memcpy( A, original, (size_t)(N*N) * sizeof( double ) );
		if ( ndarray ) {
			info = API_SUFFIX(c_dlasyf_ndarray)( uplo, N, NB, &KB, 0, A, N, 1, 0, IPIV, 1, 0, W, NB, 1, 0 );
		} else {
			info = API_SUFFIX(c_dlasyf)( LAPACK_ROW_MAJOR, uplo, N, NB, &KB, A, N, IPIV, W, NB );
		}
		if ( info != 0 || KB != expected ) {
			break;
		}
	}
	elapsed = tic() - t;
	if ( info != 0 || KB != expected ) {
		elapsed = -1.0;
	}
	start = ( uplo == LAPACK_UPPER_TRIANGLE ) ? N-expected : 0;
	stop = start + expected;
	for ( i = start; i < stop; i++ ) {
		if ( IPIV[ i ] != i+1 ) {
			elapsed = -1.0;
		}
	}
	if ( ( uplo == LAPACK_UPPER_TRIANGLE && A[ N ] != 999.0 ) || ( uplo == LAPACK_LOWER_TRIANGLE && A[ 1 ] != 999.0 ) ) {
		elapsed = -1.0;
	}
	free( original );
	free( A );
	free( W );
	free( IPIV );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const LAPACK_INT sizes[] = { 8, 16 };
	const LAPACK_UPLO uplos[] = { LAPACK_UPPER_TRIANGLE, LAPACK_LOWER_TRIANGLE };
	LAPACK_INT width;
	double elapsed;
	int count;
	int passing;
	int i;
	int j;
	int k;
	int panel;
	int r;

	count = 0;
	passing = 0;
	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				for ( panel = 0; panel < 2; panel++ ) {
					width = panel ? sizes[ i ] : 4;
					for ( r = 0; r < REPEATS; r++ ) {
						count += 1;
						printf( "# c::dlasyf:N=%d:NB=%d:uplo=%s:ndarray=%d\n", (int)sizes[ i ], (int)width, j ? "lower" : "upper", k );
						elapsed = benchmark( sizes[ i ], width, uplos[ j ], k );
						if ( elapsed < 0.0 ) {
							printf( "not ok %d benchmark failed\n", count );
						} else {
							printf( "  ---\n" );
							printf( "  iterations: %d\n", ITERATIONS );
							printf( "  elapsed: %0.9f\n", elapsed );
							printf( "  ...\n" );
							printf( "ok %d benchmark finished\n", count );
							passing += 1;
						}
					}
				}
			}
		}
	}
	printf( "1..%d\n", count );
	printf( "# total %d\n", count );
	printf( "# pass  %d\n", passing );
	if ( passing == count ) {
		printf( "# ok\n" );
		return EXIT_SUCCESS;
	}
	return EXIT_FAILURE;
}
